import { InfiniteData, useSuspenseInfiniteQuery, useQueryClient } from '@tanstack/react-query';
import axios from 'axios';
import { produce } from 'immer';
import { useCallback } from 'react';
import { DEFAULT_COMMUNITY_PAGING, DEFAULT_COMMUNITY_PARAMS } from '~/entities/community/model/constants';
import { CommunityListResponse, CommunitySearch } from '~/entities/community/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { InfiniteQueryOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { SortDirection } from '~/shared/api/dtos/enums';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import { resultify } from '~/shared/lib/utils/resultify';

export const getCmmntyManageReadList = ({ paging, search }: CommunitySearch) => {
  return resultify(
    axios.post<CommunityListResponse>(`${API_URLS.cmmntyManage('readList')}`, {
      paging,
      search,
    }),
  );
};

export const useNoticeListInfiniteQuery = (
  { paging = DEFAULT_COMMUNITY_PAGING, search = DEFAULT_COMMUNITY_PARAMS }: CommunitySearch,
  options?: InfiniteQueryOptions<
    CommunityListResponse,
    CBDCAxiosError,
    InfiniteData<CommunityListResponse>,
    readonly unknown[],
    CommunitySearch
  >,
) => {
  const queryClient = useQueryClient();

  const markAsRead = useCallback(
    async (nttManageId: string) => {
      try {
        // Update cache with immer
        queryClient.setQueriesData(
          { queryKey: queries.community.noticeList._def },
          produce((draft: InfiniteData<CommunityListResponse> | undefined) => {
            if (!draft) return;

            draft.pages.forEach((page) => {
              if (page.result?.list) {
                page.result.list.forEach((item) => {
                  if (item.nttManageId === nttManageId) {
                    item.isRead = true;
                  }
                });
              }
            });
          }),
        );
      } catch (error) {
        console.error('Failed to mark as read:', error);
        throw error;
      }
    },
    [queryClient],
  );

  const query = useSuspenseInfiniteQuery<
    CommunityListResponse,
    CBDCAxiosError,
    InfiniteData<CommunityListResponse>,
    readonly unknown[],
    CommunitySearch
  >({
    queryKey: queries.community.noticeList({ paging, search }).queryKey,
    queryFn: async ({ pageParam = { paging, search } }) => {
      const response = await getCmmntyManageReadList(pageParam);

      // Get all existing queries with the same base key
      const existingQueries = queryClient.getQueriesData<InfiniteData<CommunityListResponse>>({
        queryKey: queries.community.noticeList._def,
      });

      // Combine all items from all queries
      const allExistingItems = existingQueries.flatMap(
        ([_, data]) => data?.pages.flatMap((page) => page.result?.list || []) || [],
      );

      if (response.result?.list) {
        response.result.list = response.result.list.map((item) => ({
          ...item,
          // Check against all existing items
          isRead: allExistingItems.some((existing) => existing.nttManageId === item.nttManageId && existing.isRead),
        }));
      }

      return response;
    },
    initialPageParam: { paging, search },
    getNextPageParam: (lastPage: CommunityListResponse) => {
      if (
        Number(lastPage?.result?.paging?.totalPageCount ?? 0) <= Number(lastPage?.result?.paging?.currentPageNo ?? 0)
      ) {
        return undefined;
      }
      return {
        paging: {
          ...lastPage?.result?.paging,
          orderBy: {
            columnList: [{ columnName: 'registDt', sortDirection: SortDirection.내림차순 }],
            toSnakeCase: true,
          },
          currentPageNo: Number(lastPage?.result?.paging?.currentPageNo ?? 0) + 1,
        },
        search,
      };
    },
    staleTime: 1000 * 60,
    gcTime: Infinity,
    ...options,
  });

  return { ...query, markAsRead };
};

export const resetNoticeListQuery = () => {
  const queryClient = getGlobalQueryClient();
  queryClient.invalidateQueries({
    queryKey: queries.community.noticeList._def,
  });
};
